const glyphCache=new Map();function pathsFor(char){const key=glyphData[char]?char:char.toLowerCase();if(glyphCache.has(key))return glyphCache.get(key);const raw=glyphData[key]||glyphData[char==='.'?'dot':'dash'];const paths=raw.split('|').map(s=>s.split(' ').map(p=>p.split(',').map(Number)));const out=paths.map(points=>{const line=[];for(let i=0;i<points.length-1;i++){const p0=points[Math.max(0,i-1)],p1=points[i],p2=points[i+1],p3=points[Math.min(points.length-1,i+2)];for(let j=0;j<12;j++){const t=j/12,t2=t*t,t3=t2*t;line.push([0,1].map(k=>.5*((2*p1[k])+(-p0[k]+p2[k])*t+(2*p0[k]-5*p1[k]+4*p2[k]-p3[k])*t2+(-p0[k]+3*p1[k]-3*p2[k]+p3[k])*t3)))} }line.push(points.at(-1));return line});glyphCache.set(key,out);return out}
