export function whiteGlyphRange(text,size,first=3,last=6,progress=1){let x=0;const boxes=[];[...text].slice(0,80).forEach((ch,i)=>{const width=(ch===' '?.4:['m','w'].includes(ch.toLowerCase())?1.13:['i','l','j'].includes(ch.toLowerCase())?.49:.78)*size;if(i>=first&&i<=last){const points=inkPaths(ch,size).lines.flat(),left=Math.min(...points.map(p=>p[0]))-size*.06,right=Math.max(...points.map(p=>p[0]))+size*.06;boxes.push({x:x+left,y:-size*.6,width:(right-left)*Math.max(0,Math.min(1,progress)),height:size*2.8})}x+=width});return boxes}
